package com.example.kafka.producer; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Service; @Service public class KafkaMessageProducer{ private final KafkaTemplate<String,Object> kafkaTemplate; public KafkaMessageProducer(KafkaTemplate<String,Object> t){this.kafkaTemplate=t;} public void send(String topic,Object msg){kafkaTemplate.send(topic,msg);} }